def calc(expr: str) -> int | str:
    values = []
    operators = []
    precedence = {"+": 1, "-": 1, "*": 2, "/": 2, "%": 2, "~": 3, "^": 4}

    def apply_operator():
        op = operators.pop()

        if op == "~":
            values.append(-values.pop())
            return

        b = values.pop()
        a = values.pop()

        if op == "+":
            values.append(a + b)
        elif op == "-":
            values.append(a - b)
        elif op == "*":
            values.append(a * b)
        elif op == "^":
            if b < 0:
                raise ValueError
            values.append(pow(a, b))
        else:
            if b == 0:
                raise ZeroDivisionError
            quotient = abs(a) // abs(b)
            if (a < 0) != (b < 0):
                quotient = -quotient
            if op == "/":
                values.append(quotient)
            else:
                values.append(a - b * quotient)

    try:
        i = 0
        expecting_operand = True

        while i < len(expr):
            char = expr[i]

            if char.isspace():
                i += 1
            elif "0" <= char <= "9":
                end = i
                while end < len(expr) and "0" <= expr[end] <= "9":
                    end += 1

                value = 0
                while i < end:
                    chunk_end = min(i + 9, end)
                    value = value * (10 ** (chunk_end - i)) + int(expr[i:chunk_end])
                    i = chunk_end

                values.append(value)
                expecting_operand = False
            elif char == "(":
                operators.append(char)
                expecting_operand = True
                i += 1
            elif char == ")":
                while operators[-1] != "(":
                    apply_operator()
                operators.pop()
                expecting_operand = False
                i += 1
            elif char == "-" and expecting_operand:
                operators.append("~")
                i += 1
            else:
                while operators and operators[-1] != "(":
                    top = operators[-1]
                    if precedence[top] > precedence[char] or (
                        precedence[top] == precedence[char] and char != "^"
                    ):
                        apply_operator()
                    else:
                        break
                operators.append(char)
                expecting_operand = True
                i += 1

        while operators:
            apply_operator()

        return values[0]
    except (ZeroDivisionError, ValueError):
        return "error"
